"""Real UI serial ten-MP4 QA; Chromium is NOT physical Safari."""
from playwright.sync_api import sync_playwright
from http.server import SimpleHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
import threading,json,tempfile,subprocess,os,time
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'reports'/'remix-ten';OUT.mkdir(exist_ok=True)
class H(SimpleHTTPRequestHandler):
 def __init__(self,*a,**kw):super().__init__(*a,directory=str(ROOT/'docs'),**kw)
 def log_message(self,*a):pass
server=ThreadingHTTPServer(('127.0.0.1',0),H);threading.Thread(target=server.serve_forever,daemon=True).start();checks=[]
def check(label,cond=True):
 assert cond,label;checks.append(label);print('PASS '+label,flush=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.getenv('BROWSER_PATH') or ('/usr/bin/chromium' if Path('/usr/bin/chromium').exists() else None),headless=True,args=['--no-sandbox','--autoplay-policy=no-user-gesture-required']);context=browser.new_context(viewport={'width':390,'height':844},has_touch=True,accept_downloads=True);page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(f'http://127.0.0.1:{server.server_port}');page.wait_for_function("document.querySelector('#remix-status')?.textContent.includes('自動設計')",timeout=30000);page.click('#remix-tab')
 check('Remix tab opens and original studio preserved',page.locator('#studio-workspace').is_hidden() and page.locator('#remix-workspace').is_visible());check('Phone layout does not overflow',page.evaluate('document.documentElement.scrollWidth<=innerWidth'))
 page.select_option('#remix-reference','REMIX-IG-MERGE');page.click('#remix-design');page.wait_for_function("document.querySelectorAll('#remix-designs article').length===10");designs=page.evaluate("async()=>{const db=await import('./remix/db.js');return (await db.readAll('state')).find(r=>r.id==='plans').designs}")
 for key in ['layout','rule','ending']:check('Ten distinct '+key,len(set(d[key] for d in designs))==10)
 check('All designs retain source and deterministic seed',all(d['source_reference_id']=='REMIX-IG-MERGE' and isinstance(d['seed'],int) for d in designs));page.wait_for_function("Number(document.querySelector('#remix-canvas').dataset.time)>0.3")
 page.click('#remix-generate');page.wait_for_timeout(1200);page.click('#remix-stop');page.wait_for_function("!document.querySelector('#remix-resume').disabled",timeout=20000);page.reload();page.wait_for_function("document.querySelector('#remix-resume')&&!document.querySelector('#remix-resume').disabled",timeout=30000);page.click('#remix-tab');check('Stopped queue persists across reload','0 / 10' in page.locator('#remix-queue-info').inner_text());page.click('#remix-resume');page.wait_for_function("document.querySelector('#remix-status').textContent.includes('キュー完了')||document.querySelector('#remix-error').textContent.length>0",timeout=300000);check('Ten serial15sec recordings complete',page.locator('#remix-error').inner_text()=='' and '10 / 10' in page.locator('#remix-queue-info').inner_text())
 metas=page.evaluate("async()=>{const m=await import('./storage.js');return (await m.list()).filter(r=>r.remixDesign)}");check('Ten saved videos with actual playback checks',len(metas)==10 and all(m['remixQuality']['encoded']['decoded_nonblack_samples']==3 for m in metas));check('All videos have synthesized audio events',all(m['recordingStats']['soundEvents']>0 for m in metas));check('Frozen original designs survive recorder',set(m['remixDesign']['structuralFingerprint'] for m in metas)==set(d['structuralFingerprint'] for d in designs))
 media=[]
 for i,m in enumerate(metas):
  old=page.locator('#remix-download').get_attribute('href')
  page.locator('#remix-library article').nth(i).get_by_role('button',name='プレビュー・保存',exact=True).click();page.wait_for_function("old=>document.querySelector('#remix-download').href.startsWith('blob:')&&document.querySelector('#remix-download').getAttribute('href')!==old",arg=old)
  with page.expect_download() as event:page.click('#remix-download')
  target=OUT/(m['remixDesign']['archetype']+'.mp4');event.value.save_as(target);probe=json.loads(subprocess.check_output(['ffprobe','-v','quiet','-show_streams','-show_format','-of','json',str(target)]));streams=probe['streams'];v=next(s for s in streams if s['codec_type']=='video');check('Playable15sec MP4 '+m['remixDesign']['archetype'],(v['width'],v['height'])==(360,640) and 14<float(probe['format']['duration'])<17 and any(s['codec_type']=='audio' for s in streams));media.append({'id':m['id'],'archetype':m['remixDesign']['archetype'],'streams':[{'codec':s['codec_name'],'type':s['codec_type']} for s in streams],'bytes':target.stat().st_size,'design':m['remixDesign'],'quality':m['remixQuality']})
 # Reusing designs must produce new seeded layouts rather than duplicate videos.
 page.select_option('#remix-count','1');page.click('#remix-design');page.wait_for_function("document.querySelectorAll('#remix-designs article').length===1");page.click('#remix-generate');page.wait_for_function("document.querySelector('#remix-status').textContent.includes('キュー完了')||document.querySelector('#remix-error').textContent.length>0",timeout=45000);check('Duplicate design gets a new seed',page.locator('#remix-error').inner_text()=='');allmeta=page.evaluate("async()=>await(await import('./storage.js')).list()");check('No repeated structure fingerprint after duplicate retry',len(set(m['remixDesign']['structuralFingerprint'] for m in allmeta))==len(allmeta))
 # Long scene: continuous time, new events, no reset loops; verify determinism across drawing schedules.
 long=page.evaluate('''async()=>{const {designBatch}=await import('./remix/design.js');const {createRemixScene}=await import('./remix/scene.js');const {simulationDigest}=await import('./engine.js?v=remix1');const d=designBatch({}, {duration:90,seed:55},1)[0];const a=createRemixScene(d),b=createRemixScene(d),canvas=document.createElement('canvas');canvas.width=90;canvas.height=160;for(let t=0;t<=90;t+=.5)a.draw(canvas.getContext('2d'),90,160,t,0,true);b.draw(canvas.getContext('2d'),90,160,90,0,true);return {events:d.timeline.length,time:a.getState().time,phase:a.getState().remix.phase,same:simulationDigest(a.getState())===simulationDigest(b.getState())}}''');check('90sec scene advances continuously and deterministically',long['time']>=89.9 and long['events']>=10 and long['same'])
 check('No uncaught JavaScript errors',not errors);check('Phone layout remains within viewport',page.evaluate('document.documentElement.scrollWidth<=innerWidth'));page.screenshot(path=str(OUT/'mobile.png'),full_page=True);(OUT/'qa.json').write_text(json.dumps({'status':'PASS','iphone_safari':'UNTESTED','checks':checks,'media':media,'long_scene':long},ensure_ascii=False,indent=2));browser.close()
server.shutdown()
